    "name": "charcommand",
    "arity": {
      "min": 1,
      "max": 1
    },
    "parameterTypes": "s",
    "signatures": [
      "charcommand \"<command>\";"
    ],
    "documentation": "This command will run the given command line exactly as if it was typed in from\nthe keyboard from a character that belonged to an account which had GM level 99.\n\nThe commands can also run without an attached rid.\n\n\t// This would do the same as above, but now\n\t// it doesn't need a player attached by default.\n\tcharcommand \"#option 0 0 0 Roy\";\n\n---------------------------------------",
